import {GALAXY_CORE} from './catalog.mjs';
import {SYSTEMS,getStats,jumpDistance,systemName} from './frontier.mjs';
const links=[];for(let i=0;i<SYSTEMS.length;i++)for(let j=i+1;j<SYSTEMS.length;j++)if(jumpDistance(i,j)<12.5)links.push([i,j]);
export class GalaxyChart{
 constructor(canvas,game,view,onSelect,selected){this.canvas=canvas;this.game=game;this.view=view;this.onSelect=onSelect;this.selected=selected;this.pointers=new Map();this.moved=false;canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.setPointerCapture(e.pointerId);this.pointers.set(e.pointerId,{x:e.offsetX,y:e.offsetY});this.start={x:e.offsetX,y:e.offsetY};this.moved=this.pointers.size>1;});canvas.addEventListener('pointermove',e=>this.move(e));canvas.addEventListener('pointerup',e=>{if(!this.pointers.has(e.pointerId))return;const click=this.pointers.size===1&&!this.moved;this.pointers.delete(e.pointerId);if(click){const near=this.points.slice().sort((a,b)=>Math.hypot(a.x-e.offsetX,a.y-e.offsetY)-Math.hypot(b.x-e.offsetX,b.y-e.offsetY))[0];if(near&&Math.hypot(near.x-e.offsetX,near.y-e.offsetY)<22)onSelect(near.id);}});canvas.addEventListener('pointercancel',()=>{this.pointers.clear();this.moved=true;});canvas.addEventListener('wheel',e=>{e.preventDefault();this.zoom(e.deltaY<0?1.18:1/1.18,e.offsetX,e.offsetY);},{passive:false});this.draw();}
 move(e){const old=this.pointers.get(e.pointerId);if(!old)return;const now={x:e.offsetX,y:e.offsetY};if(this.pointers.size===2){this.moved=true;const other=[...this.pointers.entries()].find(([id])=>id!==e.pointerId)?.[1];if(other){const before=Math.hypot(old.x-other.x,old.y-other.y);if(before>3)this.zoom(Math.hypot(now.x-other.x,now.y-other.y)/before,(now.x+other.x)/2,(now.y+other.y)/2);}}else{if(Math.hypot(now.x-this.start.x,now.y-this.start.y)>5)this.moved=true;if(this.moved){this.view.x-=(now.x-old.x)/this.view.scale;this.view.y-=(now.y-old.y)/this.view.scale;this.draw();}}this.pointers.set(e.pointerId,now);}
 zoom(factor,x=this.w/2,y=this.h/2){const prev=this.view.scale,next=Math.max(.5,Math.min(30,prev*factor));this.view.x+=(x-this.w/2)*(1/prev-1/next);this.view.y+=(y-this.h/2)*(1/prev-1/next);this.view.scale=next;this.draw();}
 draw(){const c=this.canvas,r=c.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);this.w=r.width;this.h=r.height;c.width=Math.round(r.width*dpr);c.height=Math.round(r.height*dpr);const ctx=c.getContext('2d');ctx.scale(dpr,dpr);const w=r.width,h=r.height,v=this.view,s=this.game.s,all=SYSTEMS.map(sys=>({id:sys.id,x:(sys.x-v.x)*v.scale+w/2,y:(sys.y-v.y)*v.scale+h/2}));ctx.fillStyle='#07111b';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#1d344248';const gap=10*v.scale;for(let x=((w/2-v.x*v.scale)%gap+gap)%gap;x<w;x+=gap){ctx.beginPath();ctx.moveTo(x,0);ctx.lineTo(x,h);ctx.stroke();}for(let y=((h/2-v.y*v.scale)%gap+gap)%gap;y<h;y+=gap){ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke();}const core={x:(GALAXY_CORE.x-v.x)*v.scale+w/2,y:(GALAXY_CORE.y-v.y)*v.scale+h/2};
 ctx.fillStyle='#6aabbc0c';ctx.strokeStyle='#8ac4cf50';ctx.setLineDash([5,7]);ctx.beginPath();ctx.arc(core.x,core.y,GALAXY_CORE.radius*v.scale,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.setLineDash([]);
 ctx.font='12px system-ui';ctx.fillStyle='#a9b2d8';ctx.textAlign='left';ctx.fillText('UNCHARTED REACH · BEYOND THE CORE',12,24);ctx.textAlign='center';ctx.fillStyle='#8ebcbf';ctx.fillText('HUMAN EXPLORATION CORE',core.x,core.y-26*v.scale);

  const cur=all[s.system];ctx.fillStyle='#80e6d308';ctx.strokeStyle='#90efdc40';ctx.beginPath();ctx.arc(cur.x,cur.y,getStats(s).range*v.scale,0,Math.PI*2);ctx.fill();ctx.stroke();ctx.strokeStyle='#466b7a35';for(const [a,b]of links){const p=all[a],q=all[b];if(Math.max(p.x,q.x)<0||Math.min(p.x,q.x)>w||Math.max(p.y,q.y)<0||Math.min(p.y,q.y)>h)continue;ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.stroke();}if(s.route){ctx.strokeStyle='#efb677';ctx.lineWidth=2;ctx.setLineDash([5,4]);ctx.beginPath();ctx.moveTo(cur.x,cur.y);for(const id of s.route.path){ctx.lineTo(all[id].x,all[id].y);}ctx.stroke();ctx.setLineDash([]);ctx.lineWidth=1;}this.points=all.filter(p=>p.x>0&&p.x<w&&p.y>0&&p.y<h);for(const p of this.points){const sys=SYSTEMS[p.id],visited=s.visited.includes(p.id),sel=p.id===this.selected;ctx.strokeStyle=sel?'#f1b879':visited?'#91efda':sys.uncharted?'#8493ae':'#b5c8d3';ctx.fillStyle=visited?'#91efda':'#b5c8d3';ctx.beginPath();ctx.arc(p.x,p.y,sel?5:3,0,Math.PI*2);if(sys.uncharted&&!visited)ctx.stroke();else ctx.fill();if(sel||p.id===s.system){ctx.beginPath();ctx.arc(p.x,p.y,11,0,Math.PI*2);ctx.stroke();}if(v.scale>7||sel||p.id===s.system){ctx.font='12px system-ui';ctx.fillStyle=sel?'#f0c498':'#99b0bc';ctx.textAlign='center';ctx.fillText(systemName(sys,s),p.x,p.y+24);}}}
}
